def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    arity = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None

        # Small chunks also support amounts beyond Python's string-to-int limit.
        token = token.lstrip("0")
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if len(parts) != arity.get(verb, -1) or any(not p for p in parts):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, previous_balance, was_frozen in history.pop():
                if previous_balance is None:
                    balances.pop(name, None)
                else:
                    balances[name] = previous_balance

                if was_frozen:
                    frozen.add(name)
                else:
                    frozen.discard(name)
            continue

        amount = 0
        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(parts[-1])
            if amount is None:
                rejected.append(index)
                continue

        account = parts[1]

        if verb == "open":
            valid = account not in balances
        elif verb == "deposit":
            valid = account in balances and amount > 0
        elif verb == "withdraw":
            valid = (
                amount > 0
                and account in balances
                and account not in frozen
                and balances[account] >= amount
            )
        elif verb == "transfer":
            destination = parts[2]
            valid = (
                amount > 0
                and account != destination
                and account in balances
                and destination in balances
                and account not in frozen
                and balances[account] >= amount
            )
        elif verb == "freeze":
            valid = account in balances and account not in frozen
        else:  # unfreeze
            valid = account in balances and account in frozen

        if not valid:
            rejected.append(index)
            continue

        affected = (account, parts[2]) if verb == "transfer" else (account,)
        history.append(tuple(
            (name, balances.get(name), name in frozen)
            for name in affected
        ))

        if verb == "open":
            balances[account] = amount
        elif verb == "deposit":
            balances[account] += amount
        elif verb == "withdraw":
            balances[account] -= amount
        elif verb == "transfer":
            balances[account] -= amount
            balances[parts[2]] += amount
        elif verb == "freeze":
            frozen.add(account)
        else:
            frozen.remove(account)

    return balances, rejected
